package candidate

import (
	"context"
	"errors"
	"net/http"

	"github.com/XUJiahua/enterprise_agent/internal/action"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5/pgxpool"
)

// New adapts the typed bulk-approval action to the shared HTTP protocol.
// The action owns the transaction; this package only translates protocol types
// at the boundary so the two APIs remain independent.
func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	executor, err := action.New(ctx, pool, "")
	if err != nil {
		return nil, err
	}

	approve := func(ctx context.Context, identity app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		result, replayed, err := executor.BulkApprove(ctx, identity, key, ids)
		if err != nil {
			var rejection *action.Rejection
			if errors.As(err, &rejection) {
				return protocol.Result{}, false, &protocol.Rejection{Status: rejection.Status}
			}
			return protocol.Result{}, false, err
		}
		return protocol.Result{ApprovedIDs: result.ApprovedIDs}, replayed, nil
	}

	return protocol.HTTP(approve, fallback), nil
}

